// nf-core modules test gmmdemux
nextflow_process {

    name "Test Process GMMDEMUX"
    script "../main.nf"
    process "GMMDEMUX"

    tag "modules"
    tag "modules_nfcore"
    tag "gmmdemux"

    test("Standard_Multiome - 10x mtx - simple") {
        def hto
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            hto = extract(modules_testdata_base_path + 'genomics/homo_sapiens/10xgenomics/cellranger/hashing_demultiplexing/hto.tar.gz').resolve('hto')
        }
        when {
            process {
                """
                input[0] = [ [ id:'test', single_end:true ], file('${hto}'), "MS-11,MS-12" ]
                input[1] = false
                input[2] = false
                input[3] = []
                input[4] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.matrix.get(0).get(1)).exists() },
                { assert path(process.out.barcodes.get(0).get(1)).exists() },
                { assert path(process.out.features.get(0).get(1)).exists() },
                { assert path(process.out.config_report.get(0).get(1)).exists() },

            )
        }
    }

    test("Standard_Multiome - 10x mtx") {
        config "./nextflow.config"
        def hto
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            hto = extract(modules_testdata_base_path + 'genomics/homo_sapiens/10xgenomics/cellranger/hashing_demultiplexing/hto.tar.gz').resolve('hto')
        }
        when {
            process {
                """
                input[0] = [ [ id:'test', single_end:true ], file('${hto}'), "MS-11,MS-12" ]
                input[1] = true
                input[2] = true
                input[3] = []
                input[4] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.matrix.get(0).get(1)).exists() },
                { assert path(process.out.barcodes.get(0).get(1)).exists() },
                { assert path(process.out.features.get(0).get(1)).exists() },
                { assert path(process.out.config_report.get(0).get(1)).exists() },

            )
        }
    }

    test("Standard_Multiome - 10x mtx - stub") {
        config "./nextflow.config"
        options "-stub"

        when {
            process {
                """

                input[0] = [
                    [ id:'test'],
                    [],
                    "MS-11,MS-12"
                    ]
                input[1] = true
                input[2] = true
                input[3] = []
                input[4] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.matrix.get(0).get(1)).exists() },
                { assert path(process.out.barcodes.get(0).get(1)).exists() },
                { assert path(process.out.features.get(0).get(1)).exists() },
                { assert path(process.out.config_report.get(0).get(1)).exists() },
            )
        }

    }

}

params{
    // Optional parameters for GMM-demux - Default values
    threshold = 0.8
    num_cells = 11089
    examine = "example_cell_types.txt"
    ambiguous = 0.05


}

process {

    withName: GMMDEMUX {
        ext.args = "-t ${params.threshold} --summary ${params.num_cells} -a ${params.ambiguous} "
    }
}
